<script setup>
import { ref,onMounted,onBeforeUnmount,nextTick } from "vue";
import { X,Check,LockKeyhole } from "@lucide/vue";
import RankEmblem from "./RankEmblem.vue";
defineProps({honor:{type:Object,required:true},tiers:{type:Array,required:true}});
const emit=defineEmits(['close']);const dialog=ref(null);let previous;
onMounted(async()=>{previous=document.activeElement;await nextTick();dialog.value.querySelector('button')?.focus();});
onBeforeUnmount(()=>previous?.focus());
function tab(event){if(event.key==='Tab'){event.preventDefault();dialog.value.querySelector('button')?.focus();}}
</script>
<template><Teleport to="body"><div class="ui-dialog-backdrop honor-backdrop" @click.self="emit('close')" @keydown.esc="emit('close')"><section ref="dialog" class="ui-modal honor-dialog" role="dialog" aria-modal="true" aria-labelledby="honor-journey-title" @keydown="tab"><header><div><h2 id="honor-journey-title">我的荣耀之路</h2><p>累计课程积分提升段位，兑换奖品不会降低荣耀经验。</p></div><button class="icon-button" aria-label="关闭荣耀之路" @click="emit('close')"><X :size="18"/></button></header><div class="ui-modal-body"><div class="honor-current"><RankEmblem :level="honor.level" :name="honor.name" :stars="honor.stars"/><div><strong>{{ honor.experience }} <small>荣耀经验</small></strong><p>{{ honor.nextExperience==null?'已达到最高荣耀':`再获 ${honor.nextExperience-honor.experience} 积分，晋升${honor.nextName}` }}</p></div></div><div class="honor-progress" role="progressbar" :aria-valuenow="honor.progress" aria-valuemin="0" aria-valuemax="100" aria-label="下一星级进度"><span :style="{width:honor.progress+'%'}"/></div><div class="honor-tier-list"><section v-for="tier in tiers" :key="tier.level" :class="{current:tier.level===honor.level,unlocked:tier.level<=honor.level}"><RankEmblem :level="tier.level" :name="tier.name" :stars="tier.level<honor.level?5:tier.level===honor.level?honor.stars:1"/><div><strong>{{ tier.minimum }} 积分起 <small>每 {{ tier.starStep }} 分升一星</small></strong><p>{{ tier.privilege }}</p></div><Check v-if="tier.level<=honor.level" :size="16" aria-label="已达成"/><LockKeyhole v-else :size="14" aria-label="未解锁"/></section></div><p class="honor-note">共七个段位，每段五星。荣耀经验仅统计正常课程获得积分；兑换、退款及人工余额调整不改变经验。课程数据被纠正或撤销后，经验会相应重算。装扮须在“我的装扮”中选择穿戴。</p></div></section></div></Teleport></template>
